[a1ku_form]		
					<style>
/* ========================================
   HERO
   ======================================== */
.a1ku-hero {
  width: 100%;
  box-sizing: border-box;
}
.a1ku-hero-bg {
  width: 100%;
  max-width: 1400px;
  height: 571px;
  background-image: url('https://a1solar.hu/wp-content/uploads/2026/01/24233-1.jpg');
  background-size: cover;
  background-position: center;
  position: relative;
  display: flex;
  align-items: flex-end;
  padding: 40px;
  color: white;
  box-sizing: border-box;
  border-top-left-radius: 24px;
  border-top-right-radius: 24px;
  overflow: hidden;
}
.a1ku-hero-bg::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to right, #0A141Dcc 0%, rgba(10, 20, 29, 0) 100%);
  z-index: 1;
}
.a1ku-hero-logo { position: absolute; top: 40px; left: 40px; z-index: 2; }
.a1ku-hero-logo img { height: 40px; width: auto; display: block; }
.a1ku-hero-content { position: relative; z-index: 2; max-width: 600px; padding-bottom: 30px; }
.a1ku-badge {
  background-color: rgba(255, 255, 255, 0.2);
  color: white; font-size: 12px; font-weight: 500;
  text-transform: uppercase; padding: 8px 14px;
  border-radius: 999px; display: inline-block;
  margin-bottom: 20px; letter-spacing: 1px;
}
.a1ku-hero-content h1 { font-size: 38px; line-height: 1.2; font-weight: 300; margin: 0; color: white; }
.a1ku-hero-content h1 strong { font-weight: 700; }
.a1ku-formwrap {
  background: #fff; padding: 60px 40px 80px;
  max-width: 1400px; margin: 0 auto 40px;
  border-bottom-left-radius: 24px;
  border-bottom-right-radius: 24px;
  box-sizing: border-box;
}
.a1ku-form { max-width: 800px; margin: 0 auto; font-family: inherit; }
.a1ku-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px 30px; margin-bottom: 24px; align-items: start; }
.a1ku-field { display: flex; flex-direction: column; align-self: start; width: 100%; }
.a1ku-full { margin-bottom: 24px; width: 100%; }
.a1ku-field label {
  font-size: 15px; font-weight: 400; color: #1a1a1a;
  margin-bottom: 10px; line-height: 1.45;
  display: flex; align-items: center; gap: 6px; flex-wrap: wrap;
}
.a1ku-req { color: #db0330; margin-left: 2px; }
.a1ku-field small { font-size: 13px; color: #6b6b6b; margin: -4px 0 10px; line-height: 1.5; }
.a1ku-info {
  background: transparent; border: none; padding: 0;
  margin-left: 4px; cursor: pointer; color: #db0330;
  display: inline-flex; align-items: center; justify-content: center;
  border-radius: 50%; width: 22px; height: 22px;
  transition: background 0.2s, transform 0.15s; flex-shrink: 0;
}
.a1ku-info:hover { background: rgba(219, 3, 48, 0.1); transform: scale(1.1); }
.a1ku-info:focus-visible { outline: 2px solid #db0330; outline-offset: 2px; }
.a1ku-form input[type="text"],
.a1ku-form input[type="email"],
.a1ku-form input[type="tel"],
.a1ku-form input[type="date"] {
  width: 100%; padding: 18px 22px; border: none;
  border-radius: 999px; background: #f2f1ec;
  font-size: 15px; color: #1a1a1a; font-family: inherit;
  box-sizing: border-box; outline: none;
  transition: background 0.2s, box-shadow 0.2s;
}
.a1ku-form input:focus { background: #eae9e3; box-shadow: 0 0 0 2px rgba(219, 3, 48, 0.15); }
.a1ku-form input::placeholder { color: #a8a6a0; opacity: 1; }
.a1ku-form input.a1ku-error { box-shadow: 0 0 0 2px rgba(219, 3, 48, 0.4); }
.a1ku-dropzone {
  border: 2px dashed #c9c7bd; border-radius: 20px; background: #f2f1ec;
  padding: 40px 30px; transition: all 0.2s ease; cursor: pointer;
  text-align: center; width: 100%; box-sizing: border-box;
}
.a1ku-dropzone:hover, .a1ku-dropzone.a1ku-drag { border-color: #db0330; background: #eae9e3; }
.a1ku-dropzone.a1ku-error { border-color: #db0330; background: #fce7ec; }
.a1ku-dropzone-icon { color: #6b6b6b; margin-bottom: 8px; display: flex; justify-content: center; }
.a1ku-dropzone-text { font-size: 14px; color: #1a1a1a; margin-bottom: 10px; }
.a1ku-dropzone-text span { color: #6b6b6b; margin-left: 4px; }
.a1ku-dropzone-btn {
  background: #db0330; color: #fff; padding: 10px 24px;
  border-radius: 999px; font-size: 14px; font-weight: 500;
  border: none; cursor: pointer; font-family: inherit; transition: background 0.2s;
}
.a1ku-dropzone-btn:hover { background: #b10229; }
.a1ku-dropzone-filename { margin-top: 12px; font-size: 13px; color: #1a1a1a; font-weight: 500; word-break: break-all; }
.a1ku-dropzone-filename:not(:empty) {
  padding: 8px 14px; background: #fff; border-radius: 999px;
  display: inline-block; border: 1px solid #e5e4de;
}
.a1ku-emergency-header {
  font-size: 18px; font-weight: 600; color: #1a1a1a;
  margin: 30px 0 20px; padding-top: 30px; border-top: 1px solid #e5e4de;
}
.a1ku-consent { margin: 30px 0 25px; }
.a1ku-consent label {
  display: flex; align-items: flex-start; gap: 12px;
  font-size: 15px; color: #1a1a1a; line-height: 1.55; cursor: pointer;
}
.a1ku-consent input[type="checkbox"] { margin-top: 4px; width: 18px; height: 18px; accent-color: #db0330; flex-shrink: 0; }
.a1ku-consent a { color: #db0330; text-decoration: underline; text-underline-offset: 2px; }
.a1ku-consent a:hover { color: #b10229; }
.a1ku-hp { position: absolute; left: -9999px; width: 1px; height: 1px; overflow: hidden; }
.a1ku-submit-wrap { margin-top: 10px; }
.a1ku-submit {
  width: 100%; background: #db0330; color: #fff; padding: 20px;
  border: none; border-radius: 999px; font-size: 17px; font-weight: 500;
  cursor: pointer; transition: background 0.2s, transform 0.1s;
  letter-spacing: 0.3px; font-family: inherit; position: relative;
}
.a1ku-submit:hover:not(:disabled) { background: #b10229; }
.a1ku-submit:active:not(:disabled) { transform: scale(0.98); }
.a1ku-submit:disabled { cursor: not-allowed; opacity: 0.75; }
.a1ku-submit-loader {
  display: none; width: 20px; height: 20px;
  border: 2px solid rgba(255,255,255,0.3); border-top-color: #fff;
  border-radius: 50%; animation: a1ku-spin 0.7s linear infinite;
  margin-left: 12px; vertical-align: middle;
}
.a1ku-submit.a1ku-loading .a1ku-submit-loader { display: inline-block; }
@keyframes a1ku-spin { to { transform: rotate(360deg); } }
.a1ku-response {
  margin-top: 20px; padding: 16px 20px; border-radius: 12px;
  font-size: 15px; line-height: 1.5; display: none;
}
.a1ku-response.a1ku-success { display: block; background: #e8f5ec; color: #1e5c2e; border: 1px solid #b5dcc0; }
.a1ku-response.a1ku-fail { display: block; background: #fce7ec; color: #8b0a20; border: 1px solid #f4b5bf; }
.a1ku-modal {
  position: fixed; inset: 0; z-index: 99999; display: none;
  align-items: center; justify-content: center; padding: 20px; box-sizing: border-box;
}
.a1ku-modal.a1ku-open { display: flex; animation: a1ku-fade-in 0.2s ease; }
.a1ku-modal-backdrop { position: absolute; inset: 0; background: rgba(10, 20, 29, 0.6); cursor: pointer; }
.a1ku-modal-dialog {
  position: relative; background: #fff; border-radius: 20px;
  padding: 32px 36px 28px; max-width: 480px; width: 100%;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.25);
  animation: a1ku-slide-up 0.25s ease; box-sizing: border-box;
}
.a1ku-modal-close {
  position: absolute; top: 14px; right: 14px;
  background: transparent; border: none; width: 36px; height: 36px;
  border-radius: 50%; cursor: pointer; color: #6b6b6b;
  display: flex; align-items: center; justify-content: center;
  transition: background 0.2s, color 0.2s;
}
.a1ku-modal-close:hover { background: #f2f1ec; color: #1a1a1a; }
.a1ku-modal-dialog h3 {
  font-size: 20px; font-weight: 600; color: #1a1a1a;
  margin: 0 0 16px; padding-right: 32px; line-height: 1.3;
}
.a1ku-modal-dialog p { font-size: 15px; color: #3a3a3a; line-height: 1.6; margin: 0 0 12px; }
.a1ku-modal-dialog p:last-child { margin-bottom: 0; }
.a1ku-modal-dialog strong { color: #1a1a1a; font-weight: 600; }
@keyframes a1ku-fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes a1ku-slide-up { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
@media (max-width: 1024px) {
  .a1ku-hero-bg { height: 440px; padding: 30px; }
  .a1ku-hero-logo { top: 30px; left: 30px; }
  .a1ku-hero-content h1 { font-size: 32px; }
  .a1ku-formwrap { padding: 50px 30px 60px; }
}
@media (max-width: 767px) {
  .a1ku-hero { padding: 0 12px; }
  .a1ku-hero-bg { height: 380px; padding: 24px; border-top-left-radius: 18px; border-top-right-radius: 18px; }
  .a1ku-hero-bg::before { background: linear-gradient(to bottom, #0A141D80 0%, #0A141Dcc 100%); }
  .a1ku-hero-logo { top: 24px; left: 24px; }
  .a1ku-hero-logo img { height: 32px; }
  .a1ku-hero-content h1 { font-size: 26px; }
  .a1ku-badge { font-size: 11px; padding: 6px 12px; }
  .a1ku-formwrap { padding: 32px 20px 50px; margin: 0 12px 24px; border-bottom-left-radius: 18px; border-bottom-right-radius: 18px; }
  .a1ku-grid { grid-template-columns: 1fr; gap: 20px; }
  .a1ku-submit { padding: 18px; font-size: 16px; }
  .a1ku-dropzone { padding: 28px 18px; }
  .a1ku-modal-dialog { padding: 26px 24px 22px; border-radius: 16px; }
  .a1ku-modal-dialog h3 { font-size: 18px; }
  .a1ku-modal-dialog p { font-size: 14px; }
}
@media (max-width: 480px) {
  .a1ku-hero-bg { height: 340px; }
  .a1ku-hero-content h1 { font-size: 22px; }
}
/* Sikeres/hiba üzenet mindenképp látszik */
.a1ku-formwrap .a1ku-response.a1ku-success,
.a1ku-formwrap .a1ku-response.a1ku-fail {
  display: block !important;
  margin: 40px auto !important;
  max-width: 800px !important;
  text-align: center !important;
  font-size: 16px !important;
  padding: 24px 28px !important;
}
.a1ku-formwrap .a1ku-response.a1ku-success strong {
  font-size: 20px !important;
  display: block;
  margin-bottom: 6px;
}
</style>
